            {"accepted":len(rows),"unmatched":nonblank-len(rows),"nonblank":nonblank})

def dossier(base,candidate):
    if base is None or candidate is None:
        return {"status":"unavailable"}
    if base["tables"]!=candidate["tables"]:
        raise ValueError("Different tables")
    b=score(base)
    c=score(candidate)
    return {
        "status":"recomputed",
        "baseline":base["run"],"candidate":candidate["run"],
        "tables":base["tables"],
        "baseline_count":(base["wins"],base["total"]),
        "candidate_count":(candidate["wins"],candidate["total"]),
        "baseline_rate":b["rate"],"candidate_rate":c["rate"],
        "baseline_interval":b["interval"],"candidate_interval":c["interval"],
        "clxiii_delta_pp":100*(c["rate"]-b["rate"]),
        "evidence":"aggregate D3 log",
        "limitation":"paired outcomes and full manifest not verified"
    }

base,candidate,parse_audit=load_pair()
